companies = list_companies({})
first = list_contacts({ page: 1 })
rest = for p in list.range(2, first.total_pages + 1) {
  return list_contacts({ page: p }).items
}
contacts = fold acc = first.items for page in rest { return acc + page }

domain_to_company = fold acc = {} for c in companies {
  return acc + { [c.domain]: c.name }
}

results = for contact in contacts {
  email = contact.email if contact.email != null else ""
  parts = text.split(email, "@")
  domain = parts[1] if list.length(parts) == 2 else ""
  need_company = (contact.company == null or contact.company == "") and domain != "" and domain in domain_to_company
  new_company = domain_to_company[domain] if need_company else null

  phone = contact.phone if contact.phone != null else ""
  already_ok = regex.test(phone, "^\\+1\\d{10}$")
  digits = regex.replace(phone, "[^0-9]", "")
  fixed_phone = if already_ok {
    return null
  } else if text.starts_with(digits, "1") and text.length(digits) == 11 {
    return "+" + digits
  } else if text.length(digits) == 10 {
    return "+1" + digits
  } else if digits != "" {
    return "+1" + text.slice(digits, text.length(digits) - 10) if text.length(digits) > 10 else "+1" + digits
  } else {
    return null
  }
  need_phone = fixed_phone != null

  updated = update_contact({
    id: contact.id,
    phone: fixed_phone if need_phone else null,
    company: new_company if need_company else null
  }) if need_phone or need_company else null

  return {
    phone_fixed: need_phone,
    company_filled: need_company
  }
}

phones_fixed = fold acc = 0 for r in results {
  return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
  return acc + (1 if r.company_filled else 0)
}

submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submitted }

